INSERT INTO `document_templates` VALUES (1,'Pengadaan Barang','PROCUREMENT','Template untuk pengajuan pengadaan barang/peralatan','po','{\"title\":\"Pengajuan Pengadaan Barang\\/Peralatan\",\"description\":\"Permohonan persetujuan pengadaan barang\\/peralatan kantor sesuai kebutuhan operasional.\",\"priority\":\"normal\",\"vendor_name\":\"PT Supplier Indonesia\",\"item_description\":\"1. Nama Barang x jumlah unit @ Rp harga_satuan\\n2. Nama Barang x jumlah unit @ Rp harga_satuan\"}',NULL,1,1,NULL,'2026-01-14 09:26:15','2026-08-02 05:13:27'),(2,'Reimbursement','REIMBURSEMENT','Template untuk pengajuan penggantian biaya','invoice','{\"title\":\"Pengajuan Reimbursement\",\"description\":\"Permohonan penggantian biaya operasional yang telah dikeluarkan.\",\"priority\":\"normal\"}',NULL,1,1,NULL,'2026-01-14 09:26:15','2026-08-02 04:45:10'),(3,'Perjalanan Dinas','BUSINESS_TRIP','Template untuk pengajuan perjalanan dinas','only','{\"title\":\"Pengajuan Perjalanan Dinas\",\"description\":\"Permohonan persetujuan perjalanan dinas untuk keperluan operasional perusahaan.\",\"priority\":\"normal\",\"document_category\":\"surat_tugas\"}',NULL,1,1,NULL,'2026-01-14 09:26:15','2026-08-02 04:45:10'),(4,'Cuti Karyawan','LEAVE_REQUEST','Template untuk pengajuan cuti','only','{\"title\":\"Pengajuan Cuti Karyawan\",\"description\":\"Permohonan cuti sesuai ketentuan perusahaan yang berlaku.\",\"priority\":\"normal\",\"document_category\":\"lainnya\"}',NULL,1,1,'2026-08-02 05:17:02','2026-01-14 09:26:15','2026-08-02 05:17:02'),(5,'Pembelian Bulk','BULK_PURCHASE','Template untuk pengajuan pembelian dalam jumlah besar','po','{\"title\":\"Pengajuan Pembelian Bulk\",\"description\":\"Permohonan persetujuan pembelian dalam jumlah besar untuk kebutuhan operasional.\",\"priority\":\"high\",\"vendor_name\":\"PT Distributor Utama\",\"item_description\":\"1. Nama Barang x jumlah unit @ Rp harga_satuan\\n2. Nama Barang x jumlah unit @ Rp harga_satuan\"}',NULL,1,1,NULL,'2026-01-14 09:26:15','2026-08-02 05:13:27'),(6,'Pinjaman Karyawan','EMPLOYEE_LOAN','Template untuk pengajuan pinjaman karyawan - wajib persetujuan Presiden Direktur','loan','{\"title\":\"Pengajuan Pinjaman Karyawan\",\"description\":\"Permohonan pinjaman karyawan dengan skema potong gaji bulanan.\",\"priority\":\"normal\",\"loan_type\":\"darurat\",\"loan_reason\":\"Kebutuhan mendesak untuk keperluan pribadi\\/keluarga.\"}',NULL,1,1,NULL,'2026-01-14 09:26:15','2026-08-02 04:45:10'),(7,'PO Langganan Cloud Bulanan','PO-CLOUD','Template untuk perpanjangan langganan cloud server bulanan','po','{\"title\":\"Pengajuan Perpanjangan Cloud Server\",\"priority\":\"normal\",\"budget_code\":\"IT-2026-CLOUD\",\"description\":\"Pengajuan perpanjangan langganan cloud server untuk periode bulan berikutnya. Mohon approval untuk melanjutkan layanan.\",\"vendor_name\":\"PT Amazon Web Services Indonesia\",\"item_description\":\"1. AWS EC2 Instance (t3.medium) x 2 unit\\n2. AWS RDS Database x 1 unit\\n3. AWS S3 Storage 100GB x 1 paket\"}',NULL,1,1,NULL,'2026-05-12 16:13:43','2026-08-02 05:13:27'),(8,'Memo Internal Kebijakan','MEMO-POLICY','Template untuk memo internal terkait kebijakan baru atau perubahan SOP','only','{\"title\": \"Memo Internal: Kebijakan Baru\", \"priority\": \"normal\", \"description\": \"Dengan ini disampaikan kebijakan baru yang berlaku efektif sejak tanggal yang tercantum.\", \"document_category\": \"memo\"}',NULL,1,1,NULL,'2026-05-12 16:13:44','2026-05-12 16:13:44'),(9,'Invoice Tagihan Bulanan','INV-MONTHLY','Template untuk pembayaran tagihan vendor berlangganan bulanan','invoice','{\"title\": \"Pembayaran Tagihan Bulanan\", \"priority\": \"normal\", \"description\": \"Pengajuan pembayaran tagihan bulanan dari vendor sesuai kontrak yang berlaku.\"}',NULL,1,1,NULL,'2026-05-12 16:13:44','2026-05-12 16:13:44');
