INSERT INTO `email_templates` VALUES (1,'EML-01','Approval Only - Next Approver','only','next_approver','[ConfirmMe] Mohon Review: {{doc_subject}}','Halo {{next_approver_name}},','Ada dokumen **{{doc_id}}** dari {{staff_name}} yang memerlukan review Anda.','{\"type\": \"next_approver\"}','{\"include_requester\": true, \"include_previous_approvers\": false}',1,'Template untuk dokumen Approval Only ke approver berikutnya','2026-01-15 03:10:42','2026-01-15 03:10:42'),(2,'EML-02','PO - Next Approver','po','next_approver','[ConfirmMe] Persetujuan PO: {{vendor_name}}','Yth. {{next_approver_name}},','Pengajuan PO **{{doc_id}}** telah disetujui oleh {{prev_approver_name}} dan menunggu otorisasi Anda.','{\"type\": \"next_approver\"}','{\"include_requester\": true, \"include_previous_approvers\": true}',1,'Template untuk PO ke approver berikutnya (bukan presiden)','2026-01-15 03:10:42','2026-01-15 03:10:42'),(3,'EML-03','PO - Presiden Direktur','po','presiden','[ConfirmMe] Final Approval PO: {{doc_id}}','Yth. Bpk **Kromo Semitro** ,','Dokumen PO senilai **{{amount}}** telah diverifikasi lengkap oleh Finance dan siap untuk persetujuan akhir.','{\"type\": \"presiden_direktur\"}','{\"include_requester\": true, \"include_finance_director\": true, \"include_division_director\": true, \"include_previous_approvers\": true}',1,'Template untuk PO ke Presiden Direktur (final approval)','2026-01-15 03:10:42','2026-05-06 13:16:34'),(4,'EML-04','PO - Final Approved','po','completed','[ConfirmMe] PO {{doc_id}} APPROVED - Final','Selamat {{staff_name}},','PO Anda telah disetujui final oleh **Bpk. Kromo Semitro**. Silakan cek lampiran untuk dokumen ber-QR Code.','{\"type\": \"requester\"}','{\"include_finance\": true, \"include_previous_approvers\": true}',1,'Template notifikasi PO selesai disetujui ke pemohon','2026-01-15 03:10:42','2026-05-06 13:16:34'),(5,'EML-05','Invoice - Finance','invoice','finance','[ConfirmMe] Verifikasi Dana Invoice: {{vendor_name}}','Halo Tim Finance,','Invoice **{{doc_id}}** telah diverifikasi Supervisor. Mohon lakukan pengecekan ketersediaan dana sebelum ke Direktur.','{\"type\": \"finance\"}','{\"include_requester\": true, \"include_previous_approvers\": true}',1,'Template untuk Invoice ke Finance untuk verifikasi dana','2026-01-15 03:10:42','2026-01-15 03:10:42'),(6,'EML-06','Loan - HR/Finance','loan','hr_finance','[ConfirmMe] Verifikasi Pinjaman: {{staff_name}}','Yth. Tim HR/Finance,','Terdapat permohonan pinjaman dari {{staff_name}}. Mohon verifikasi kelayakan sesuai kebijakan perusahaan.','{\"type\": \"next_approver\"}','{\"include_requester\": true, \"include_previous_approvers\": true}',1,'Template untuk Loan ke HR dan Finance untuk verifikasi','2026-01-15 03:10:42','2026-01-15 03:10:42'),(7,'EML-07','Loan - Presiden Direktur','loan','presiden','[ConfirmMe] Final Approval Loan: {{staff_name}}','Yth. Bpk **Kromo Semitro** ,','Permohonan pinjaman {{staff_name}} telah disetujui oleh Direktur HR dan Finance. Mohon keputusan akhir Anda.','{\"type\": \"presiden_direktur\"}','{\"include_finance\": true, \"include_requester\": true, \"include_hr_director\": true, \"include_previous_approvers\": true}',1,'Template untuk Loan ke Presiden Direktur (final approval)','2026-01-15 03:10:42','2026-05-06 13:16:35'),(8,'EML-08','Dokumen Ditolak','all','rejected','[ConfirmMe] Dokumen DITOLAK: {{doc_id}}','Halo {{staff_name}},','Dokumen Anda **{{doc_id}}** telah ditolak oleh {{rejected_by_name}}. Alasan: {{reason}}.','{\"type\": \"requester\"}','{\"include_previous_approvers\": true}',1,'Template notifikasi penolakan dokumen untuk semua jenis workflow','2026-01-15 03:10:42','2026-01-15 03:10:42'),(9,'EML-09','Invoice - Presiden Direktur','invoice','presiden','[ConfirmMe] Final Approval Invoice: {{doc_id}}','Yth. Bpk **Kromo Semitro** ,','Invoice **{{doc_id}}** senilai **{{amount}}** telah diverifikasi oleh Finance dan Direktur. Mohon persetujuan akhir Anda.','{\"type\": \"presiden_direktur\"}','{\"include_requester\": true, \"include_finance_director\": true, \"include_previous_approvers\": true}',1,'Template untuk Invoice ke Presiden Direktur (final approval)','2026-01-15 03:10:42','2026-05-06 13:16:35'),(10,'EML-10','Dokumen Selesai','all','completed','[ConfirmMe] Dokumen {{doc_id}} - APPROVED','Selamat {{staff_name}},','Dokumen **{{doc_id}}** telah selesai diproses dan disetujui oleh semua pihak.','{\"type\": \"requester\"}','{\"include_previous_approvers\": true}',1,'Template notifikasi dokumen selesai disetujui (generic)','2026-01-15 03:10:42','2026-01-15 03:10:42');
